begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('00000000-0000-0000-0000-000000000091','import1@example.test','{"username":"import_one"}'),
 ('00000000-0000-0000-0000-000000000092','import2@example.test','{"username":"import_two"}');
create function pg_temp.payload(key text default 'tradingview:one') returns jsonb language sql as $$
 select jsonb_build_array(jsonb_build_object('sourceKey',key,'symbol','ES','side','long','entryPrice','100','exitPrice','102','openedAt','2026-10-26T10:00:00Z','sourcePnlUsd','12.1234567890123456789','quantity','0.1234567890123456789'));
$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000091',true);
select is(public.import_trade_history(pg_temp.payload()), '{"inserted":1,"alreadyPresent":0}'::jsonb,'imports one trade');
select ok((select original_note is null and stop_price is null and setup is null and r_result is null from public.trades),'missing details and R stay null');
select is((select source_net_pnl_usd from public.trades),12.1234567890123456789::numeric,'preserves P&L precision');
select is((select source_quantity from public.trades),0.1234567890123456789::numeric,'preserves quantity precision');
select is(public.import_trade_history(pg_temp.payload()),'{"inserted":0,"alreadyPresent":1}'::jsonb,'identical reimport is idempotent');
update public.trades set stop_price=99,setup='breakout',exit_price=103;
select is((select r_result from public.trades),3::numeric,'adding a stop calculates R');
select is(public.import_trade_history(pg_temp.payload()),'{"inserted":0,"alreadyPresent":1}'::jsonb,'reimport preserves edited prices');
select is((select exit_price from public.trades),103::numeric,'reimport does not overwrite corrections');
select throws_ok($$select public.import_trade_history(jsonb_set(pg_temp.payload(),'{0,exitPrice}','"104"'))$$,'23505',null,'changed source conflicts');
select throws_ok($$select public.import_trade_history(pg_temp.payload('tradingview:new') || jsonb_set(pg_temp.payload(),'{0,quantity}','"bad"'))$$,'22023',null,'malformed row rejected');
select is((select count(*) from public.trades),1::bigint,'failed batch rolls back earlier inserts');
select throws_ok($$select public.import_trade_history(pg_temp.payload('tradingview:new') || jsonb_set(pg_temp.payload(),'{0,exitPrice}','"104"'))$$,'23505',null,'conflict rejects entire batch');
select is((select count(*) from public.trades),1::bigint,'conflict rolls back earlier inserts');
select throws_ok($$select public.import_trade_history(pg_temp.payload() || pg_temp.payload())$$,'22023',null,'duplicate identifiers rejected');
select throws_ok($$select public.import_trade_history('{}')$$,'22023',null,'object payload rejected');
select throws_ok($$select public.import_trade_history(null)$$,'22023',null,'null payload rejected');
select throws_ok($$select public.import_trade_history('[]')$$,'22023',null,'empty payload rejected');
select throws_ok($$select public.import_trade_history(jsonb_set(pg_temp.payload(),'{0,openedAt}','"2026-10-26"'))$$,'22023',null,'timezone required');
select throws_ok($$select public.import_trade_history(jsonb_set(pg_temp.payload(),'{0,sourcePnlUsd}','"NaN"'))$$,'22023',null,'nonfinite money rejected');
select throws_ok($$select public.import_trade_history(jsonb_set(pg_temp.payload(),'{0,ownerId}','"other"'))$$,'22023',null,'owner injection rejected');
select throws_ok($$insert into public.trades(owner_id,symbol,side,entry_price,opened_at,idempotency_key) values(auth.uid(),'ES','long',100,now(),gen_random_uuid())$$,'23514',null,'manual details remain required');
select throws_ok($$update public.trades set source_net_pnl_usd=99$$,'23514',null,'source data immutable');
select throws_ok($$select public.import_trade_history((select jsonb_agg(pg_temp.payload('tradingview:' || n)->0) from generate_series(1,2501) n))$$,'22023',null,'oversized trade count rejected');
select throws_ok($$select public.import_trade_history(jsonb_set(pg_temp.payload(),'{0,openedAt}','"2026-02-30T10:00:00Z"'))$$,'22023',null,'invalid calendar date rejected');
select throws_ok($$select public.import_trade_history(jsonb_set(pg_temp.payload(),'{0,quantity}','"0"'))$$,'22023',null,'zero quantity rejected');
select throws_ok($$select public.import_trade_history(jsonb_set(pg_temp.payload(),'{0,entryPrice}','100'))$$,'22023',null,'numeric values require exact strings');
select throws_ok($$select public.import_trade_history(jsonb_set(pg_temp.payload(),'{0,symbol}','null'))$$,'22023',null,'null fields rejected');
select throws_ok($$update public.trades set source_payload='{}'$$,'23514',null,'source snapshot immutable');
select throws_ok($$update public.trades set stop_price=101$$,'23514',null,'imported stop must remain on loss side');
select is(public.import_trade_history(jsonb_set(pg_temp.payload(),'{0,entryPrice}','"100.00"')),'{"inserted":0,"alreadyPresent":1}'::jsonb,'equivalent decimal formatting is idempotent');
select throws_ok($$insert into public.trades(owner_id,original_note,symbol,side,entry_price,stop_price,setup,opened_at,idempotency_key) values(auth.uid(),null,'ES','long',100,99,'setup',now(),gen_random_uuid())$$,'23514',null,'manual note required');
select throws_ok($$insert into public.trades(owner_id,original_note,symbol,side,entry_price,stop_price,setup,opened_at,idempotency_key) values(auth.uid(),'note','ES','long',100,null,'setup',now(),gen_random_uuid())$$,'23514',null,'manual stop required');
select throws_ok($$insert into public.trades(owner_id,original_note,symbol,side,entry_price,stop_price,setup,opened_at,idempotency_key) values(auth.uid(),'note','ES','long',100,99,null,now(),gen_random_uuid())$$,'23514',null,'manual setup required');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000092',true);
select is((select count(*) from public.trades),0::bigint,'other owner cannot read imported data');
select is(public.import_trade_history(pg_temp.payload()),'{"inserted":1,"alreadyPresent":0}'::jsonb,'same source belongs independently to each owner');
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.import_trade_history(pg_temp.payload())$$,'28000',null,'missing auth rejected');
reset role;
select ok(not has_function_privilege('anon','public.import_trade_history(jsonb)','EXECUTE'),'anonymous execution denied');
select ok(not (select prosecdef from pg_proc where oid='public.import_trade_history(jsonb)'::regprocedure),'RPC uses invoker RLS');
select * from finish();
rollback;
